def fetch_html(url, headers=None, max_length=None, start_index=None, **_extra):
    import json, os, datetime, time, re, hashlib, urllib.request, urllib.error, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0185000" if __import__("os").path.isdir("./environment_mix/0185000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{hashlib.sha256(os.urandom(16)).hexdigest()[:10]}"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_usage(api_key_id, fetch_request_id, event_type, tool_name, http_status_code=None, upstream_body_bytes=None, returned_chars=None, cache_hit=None):
        usage = _load("usage_events.json")
        ev = {
            "id": _new_id("ue"),
            "api_key_id": api_key_id,
            "fetch_request_id": fetch_request_id,
            "event_type": event_type,
            "tool_name": tool_name,
            "http_status_code": http_status_code,
            "upstream_body_bytes": upstream_body_bytes,
            "returned_chars": returned_chars,
            "cache_hit": cache_hit,
            "occurred_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        usage.append(ev)
        _save("usage_events.json", usage)
        return ev

    def _pick_active_key():
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("status") == "active":
                return k
        return None

    def _sanitize_headers(h):
        if h is None:
            return None
        if not isinstance(h, dict):
            return _err("VALIDATION_ERROR", "headers must be an object")
        hop_by_hop = {
            "connection", "keep-alive", "proxy-authenticate", "proxy-authorization",
            "te", "trailer", "transfer-encoding", "upgrade",
            "host", "content-length"
        }
        out = {}
        for kk, vv in h.items():
            if not isinstance(kk, str):
                continue
            lk = kk.strip().lower()
            if lk in hop_by_hop:
                continue
            if lk.startswith("sec-") or lk in {"cookie"}:
                continue
            if vv is None:
                continue
            if not isinstance(vv, (str, int, float, bool)):
                continue
            out[kk.strip()] = str(vv)
        return out

    def _norm_url(u):
        p = urllib.parse.urlsplit(u)
        scheme = p.scheme.lower()
        netloc = p.netloc
        path = p.path or "/"
        query = p.query
        frag = ""  # drop fragment
        # lowercase scheme/host
        host = netloc
        if "@" in host:
            userinfo, host = host.rsplit("@", 1)
            host = host  # keep userinfo as-is? drop for normalization
            netloc = host
        if ":" in host:
            h, port = host.rsplit(":", 1)
            if port.isdigit():
                porti = int(port)
                if (scheme == "http" and porti == 80) or (scheme == "https" and porti == 443):
                    netloc = h.lower()
                else:
                    netloc = f"{h.lower()}:{porti}"
            else:
                netloc = host.lower()
        else:
            netloc = host.lower()
        # collapse multiple slashes in path
        path = re.sub(r"/{2,}", "/", path)
        return urllib.parse.urlunsplit((scheme, netloc, path, query, frag))

    def _slice_text(full_text, sidx, mlen):
        n = len(full_text)
        s = min(max(sidx, 0), n)
        e = min(s + mlen, n)
        return full_text[s:e], n, s, mlen

    def _enforce_limits(api_key_row, tool_name_for_events):
        # rate limit: count request_accepted in last 60s must be <= rpm; reject if would exceed
        usage = _load("usage_events.json")
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt_60 = 0
        for ev in usage:
            if ev.get("api_key_id") != api_key_row.get("id"):
                continue
            if ev.get("event_type") != "request_accepted":
                continue
            t = _parse_dt(ev.get("occurred_at"))
            if t and t >= window_start:
                cnt_60 += 1
        rpm = api_key_row.get("rate_limit_rpm")
        if isinstance(rpm, int) and rpm >= 1:
            if cnt_60 + 1 > rpm:
                return _err("RATE_LIMIT", "rate limit exceeded")

        # monthly request quota: must be < quota before accepting new request
        mrq = api_key_row.get("monthly_request_quota")
        if mrq is not None:
            if not isinstance(mrq, int) or mrq < 0:
                return _err("VALIDATION_ERROR", "monthly_request_quota misconfigured")
            month_start = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            mcnt = 0
            for ev in usage:
                if ev.get("api_key_id") != api_key_row.get("id"):
                    continue
                if ev.get("event_type") != "request_accepted":
                    continue
                t = _parse_dt(ev.get("occurred_at"))
                if t and t >= month_start:
                    mcnt += 1
            if mcnt >= mrq:
                return _err("QUOTA_EXCEEDED", "monthly request quota exceeded")

        # monthly byte quota: sum returned_chars for response_returned in month must be < quota before accepting
        mbq = api_key_row.get("monthly_byte_quota")
        if mbq is not None:
            if not isinstance(mbq, int) or mbq < 0:
                return _err("VALIDATION_ERROR", "monthly_byte_quota misconfigured")
            month_start = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            total = 0
            for ev in usage:
                if ev.get("api_key_id") != api_key_row.get("id"):
                    continue
                if ev.get("event_type") != "response_returned":
                    continue
                t = _parse_dt(ev.get("occurred_at"))
                if t and t >= month_start:
                    rc = ev.get("returned_chars")
                    if isinstance(rc, int) and rc >= 0:
                        total += rc
            if total >= mbq:
                return _err("QUOTA_EXCEEDED", "monthly byte quota exceeded")
        return None

    # Validate inputs
    if not isinstance(url, str) or not url:
        return _err("VALIDATION_ERROR", "url is required and must be a string")
    if not (url.startswith("http://") or url.startswith("https://")):
        return _err("VALIDATION_ERROR", "url must start with http:// or https://")
    if max_length is None:
        max_length = 5000
    if start_index is None:
        start_index = 0
    if not isinstance(max_length, (int, float)) or isinstance(max_length, bool):
        return _err("VALIDATION_ERROR", "max_length must be a number")
    if not isinstance(start_index, (int, float)) or isinstance(start_index, bool):
        return _err("VALIDATION_ERROR", "start_index must be a number")
    try:
        max_length = int(max_length)
        start_index = int(start_index)
    except Exception:
        return _err("VALIDATION_ERROR", "max_length and start_index must be numbers")
    if max_length < 1 or max_length > 200000:
        return _err("VALIDATION_ERROR", "max_length must be between 1 and 200000")
    if start_index < 0 or start_index > 100000000:
        return _err("VALIDATION_ERROR", "start_index must be >= 0")

    sanitized_headers = _sanitize_headers(headers)
    if isinstance(sanitized_headers, dict) is False and sanitized_headers is not None:
        return sanitized_headers  # validation error

    api_key = _pick_active_key()
    if not api_key:
        # No request logging possible without a key row; return UNAUTHORIZED
        return _err("UNAUTHORIZED", "no active API key available")

    # enforce key status (must be active)
    if api_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active")

    # Rate limit & quotas before creating fetch_requests row
    limit_err = _enforce_limits(api_key, "fetch_html")
    if limit_err:
        return limit_err

    # Create fetch_requests row (queued -> running -> succeeded/failed)
    fr_id = _new_id("fr")
    normalized_url = _norm_url(url)
    fetch_requests = _load("fetch_requests.json")
    fr = {
        "id": fr_id,
        "api_key_id": api_key.get("id"),
        "tool_name": "fetch_html",
        "url": url,
        "normalized_url": normalized_url,
        "headers": sanitized_headers,
        "max_length": max_length,
        "start_index": start_index,
        "status": "queued",
        "requested_at": now,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "cache_policy": "use_cache",
        "cache_hit": False,
        "created_at": now,
        "updated_at": now,
    }
    fetch_requests.append(fr)
    _save("fetch_requests.json", fetch_requests)

    # usage: request accepted
    _log_usage(api_key.get("id"), fr_id, "request_accepted", "fetch_html", cache_hit=False)

    # Transition to running
    fr["status"] = "running"
    fr["started_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    fr["updated_at"] = fr["started_at"]
    # persist update
    for i, r in enumerate(fetch_requests):
        if r.get("id") == fr_id:
            fetch_requests[i] = fr
            break
    _save("fetch_requests.json", fetch_requests)

    # Upstream fetch (offline-safe: attempt real HTTP, but on failure mark failed)
    status_code = None
    final_url = url
    resp_headers = None
    content_type = None
    charset = None
    body_bytes = 0
    body_text = ""
    sha256_hex = None
    redirect_count = 0
    cache_hit = False

    try:
        req = urllib.request.Request(url, headers=(sanitized_headers or {}), method="GET")
        with urllib.request.urlopen(req, timeout=15) as resp:
            final_url = resp.geturl() or url
            status_code = getattr(resp, "status", None) or resp.getcode()
            resp_headers = dict(resp.headers.items()) if hasattr(resp, "headers") else None
            ctype = resp.headers.get("Content-Type") if hasattr(resp, "headers") else None
            content_type = ctype
            if ctype and "charset=" in ctype.lower():
                m = re.search(r"charset\s*=\s*([^\s;]+)", ctype, flags=re.I)
                if m:
                    charset = m.group(1).strip("\"'").lower()
            raw = resp.read()
            body_bytes = len(raw)
            sha256_hex = hashlib.sha256(raw).hexdigest()
            # decode
            dec = charset or "utf-8"
            try:
                body_text = raw.decode(dec, errors="replace")
            except Exception:
                body_text = raw.decode("utf-8", errors="replace")
    except urllib.error.HTTPError as e:
        status_code = getattr(e, "code", None) or 0
        final_url = getattr(e, "url", None) or url
        try:
            resp_headers = dict(e.headers.items()) if getattr(e, "headers", None) else None
            ctype = e.headers.get("Content-Type") if getattr(e, "headers", None) else None
            content_type = ctype
        except Exception:
            resp_headers = None
            content_type = None
        try:
            raw = e.read()
        except Exception:
            raw = b""
        body_bytes = len(raw)
        sha256_hex = hashlib.sha256(raw).hexdigest() if raw is not None else None
        body_text = raw.decode("utf-8", errors="replace") if raw else ""
    except urllib.error.URLError as e:
        # mark failed
        fr["status"] = "failed"
        fr["error_code"] = "dns_error" if "Name or service not known" in str(e.reason) else "network_error"
        fr["error_message"] = str(e.reason) if hasattr(e, "reason") else str(e)
        fr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        fr["updated_at"] = fr["finished_at"]
        for i, r in enumerate(fetch_requests):
            if r.get("id") == fr_id:
                fetch_requests[i] = fr
                break
        _save("fetch_requests.json", fetch_requests)
        _log_usage(api_key.get("id"), fr_id, "request_failed", "fetch_html", cache_hit=False)
        return _err("NOT_FOUND", "upstream fetch failed", fetch_request_id=fr_id, upstream_error=fr["error_code"])

    fetched_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Record http_response (unique by fetch_request_id)
    http_responses = _load("http_responses.json")
    hr_id = _new_id("hr")
    hr = {
        "id": hr_id,
        "fetch_request_id": fr_id,
        "final_url": final_url,
        "redirect_count": redirect_count,
        "status_code": int(status_code) if status_code is not None else 0,
        "response_headers": resp_headers,
        "content_type": content_type,
        "charset": charset,
        "body_bytes": int(body_bytes),
        "body_storage": "inline",
        "body_inline": body_text,
        "body_blob_ref": None,
        "sha256": sha256_hex,
        "fetched_at": fetched_at,
        "created_at": fetched_at,
        "updated_at": fetched_at,
    }
    # enforce uniqueness: if exists, treat as conflict
    for existing in http_responses:
        if existing.get("fetch_request_id") == fr_id:
            fr["status"] = "failed"
            fr["error_code"] = "internal_conflict"
            fr["error_message"] = "http_response already exists for request"
            fr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            fr["updated_at"] = fr["finished_at"]
            for i, r in enumerate(fetch_requests):
                if r.get("id") == fr_id:
                    fetch_requests[i] = fr
                    break
            _save("fetch_requests.json", fetch_requests)
            _log_usage(api_key.get("id"), fr_id, "request_failed", "fetch_html", http_status_code=hr.get("status_code"), upstream_body_bytes=body_bytes, cache_hit=cache_hit)
            return _err("CONFLICT", "duplicate http_response for fetch_request_id", fetch_request_id=fr_id)

    http_responses.append(hr)
    _save("http_responses.json", http_responses)
    _log_usage(api_key.get("id"), fr_id, "upstream_fetched", "fetch_html", http_status_code=hr["status_code"], upstream_body_bytes=body_bytes, cache_hit=cache_hit)

    # For html tool, converted output is HTML as fetched
    full_out = body_text if body_text is not None else ""
    sliced, full_len, sidx, mlen = _slice_text(full_out, start_index, max_length)

    fetch_outputs = _load("fetch_outputs.json")
    fo_id = _new_id("fo")
    fo = {
        "id": fo_id,
        "fetch_request_id": fr_id,
        "format": "html",
        "full_length_chars": int(full_len),
        "start_index": int(sidx),
        "max_length": int(mlen),
        "returned_length_chars": int(len(sliced)),
        "content_storage": "inline",
        "content_inline": sliced,
        "content_blob_ref": None,
        "json_value": None,
        "parse_warnings": None,
        "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
    }
    for existing in fetch_outputs:
        if existing.get("fetch_request_id") == fr_id:
            fr["status"] = "failed"
            fr["error_code"] = "internal_conflict"
            fr["error_message"] = "fetch_output already exists for request"
            fr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            fr["updated_at"] = fr["finished_at"]
            for i, r in enumerate(fetch_requests):
                if r.get("id") == fr_id:
                    fetch_requests[i] = fr
                    break
            _save("fetch_requests.json", fetch_requests)
            _log_usage(api_key.get("id"), fr_id, "request_failed", "fetch_html", http_status_code=hr["status_code"], upstream_body_bytes=body_bytes, cache_hit=cache_hit)
            return _err("CONFLICT", "duplicate fetch_output for fetch_request_id", fetch_request_id=fr_id)
    fetch_outputs.append(fo)
    _save("fetch_outputs.json", fetch_outputs)

    # Transition to succeeded
    fr["status"] = "succeeded"
    fr["cache_policy"] = "use_cache"
    fr["cache_hit"] = bool(cache_hit)
    fr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    fr["updated_at"] = fr["finished_at"]
    for i, r in enumerate(fetch_requests):
        if r.get("id") == fr_id:
            fetch_requests[i] = fr
            break
    _save("fetch_requests.json", fetch_requests)

    _log_usage(api_key.get("id"), fr_id, "response_returned", "fetch_html", http_status_code=hr["status_code"], upstream_body_bytes=body_bytes, returned_chars=len(sliced), cache_hit=cache_hit)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "fetch_request": fr,
        "http_response": hr,
        "output": fo,
        "meta": {
            "latency_ms": latency_ms
        }
    }

