        sha256_hex = hashlib.sha256(raw).hexdigest() if raw is not None else None
        body_text = raw.decode("utf-8", errors="replace") if raw else ""
    except urllib.error.URLError as e:
        fr["status"] = "failed"
        fr["error_code"] = "network_error"
        fr["error_message"] = str(e.reason) if hasattr(e, "reason") else str(e)
        fr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        fr["updated_at"] = fr["finished_at"]
        for i, r in enumerate(fetch_requests):
            if r.get("id") == fr_id:
                fetch_requests[i] = fr
                break
        _save("fetch_requests.json", fetch_requests)
        _log_usage(api_key.get("id"), fr_id, "request_failed", "fetch_txt", cache_hit=False)
        return _err("NOT_FOUND", "upstream fetch failed", fetch_request_id=fr_id, upstream_error=fr["error_code"])

    fetched_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    http_responses = _load("http_responses.json")
    hr_id = _new_id("hr")
    hr = {
        "id": hr_id,
        "fetch_request_id": fr_id,
        "final_url": final_url,
        "redirect_count": redirect_count,
        "status_code": int(status_code) if status_code is not None else 0,
        "response_headers": resp_headers,
        "content_type": content_type,
        "charset": charset,
        "body_bytes": int(body_bytes),
        "body_storage": "inline",
        "body_inline": body_text,
        "body_blob_ref": None,
        "sha256": sha256_hex,
        "fetched_at": fetched_at,
        "created_at": fetched_at,
        "updated_at": fetched_at,
    }
    for existing in http_responses:
        if existing.get("fetch_request_id") == fr_id:
            fr["status"] = "failed"
            fr["error_code"] = "internal_conflict"
            fr["error_message"] = "http_response already exists for request"
            fr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            fr["updated_at"] = fr["finished_at"]
            for i, r in enumerate(fetch_requests):
                if r.get("id") == fr_id:
                    fetch_requests[i] = fr
                    break
            _save("fetch_requests.json", fetch_requests)
            _log_usage(api_key.get("id"), fr_id, "request_failed", "fetch_txt", http_status_code=hr.get("status_code"), upstream_body_bytes=body_bytes, cache_hit=cache_hit)
            return _err("CONFLICT", "duplicate http_response for fetch_request_id", fetch_request_id=fr_id)
    http_responses.append(hr)
    _save("http_responses.json", http_responses)
    _log_usage(api_key.get("id"), fr_id, "upstream_fetched", "fetch_txt", http_status_code=hr["status_code"], upstream_body_bytes=body_bytes, cache_hit=cache_hit)

    text, warnings = _html_to_text(body_text or "")
    sliced, full_len, sidx, mlen = _slice_text(text, start_index, max_length)

    fetch_outputs = _load("fetch_outputs.json")
    fo_id = _new_id("fo")
    fo = {
        "id": fo_id,
        "fetch_request_id": fr_id,
        "format": "text",
        "full_length_chars": int(full_len),
        "start_index": int(sidx),
        "max_length": int(mlen),
        "returned_length_chars": int(len(sliced)),
        "content_storage": "inline",
        "content_inline": sliced,
        "content_blob_ref": None,
        "json_value": None,
        "parse_warnings": warnings,
        "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
    }
    for existing in fetch_outputs:
        if existing.get("fetch_request_id") == fr_id:
            fr["status"] = "failed"
            fr["error_code"] = "internal_conflict"
            fr["error_message"] = "fetch_output already exists for request"
            fr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            fr["updated_at"] = fr["finished_at"]
            for i, r in enumerate(fetch_requests):
                if r.get("id") == fr_id:
                    fetch_requests[i] = fr
                    break
            _save("fetch_requests.json", fetch_requests)
            _log_usage(api_key.get("id"), fr_id, "request_failed", "fetch_txt", http_status_code=hr["status_code"], upstream_body_bytes=body_bytes, cache_hit=cache_hit)
            return _err("CONFLICT", "duplicate fetch_output for fetch_request_id", fetch_request_id=fr_id)
    fetch_outputs.append(fo)
    _save("fetch_outputs.json", fetch_outputs)

    fr["status"] = "succeeded"
    fr["cache_policy"] = "use_cache"
    fr["cache_hit"] = bool(cache_hit)
    fr["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    fr["updated_at"] = fr["finished_at"]
    for i, r in enumerate(fetch_requests):
        if r.get("id") == fr_id:
            fetch_requests[i] = fr
            break
    _save("fetch_requests.json", fetch_requests)

    _log_usage(api_key.get("id"), fr_id, "response_returned", "fetch_txt", http_status_code=hr["status_code"], upstream_body_bytes=body_bytes, returned_chars=len(sliced), cache_hit=cache_hit)

    latency_ms = int((time.time() - t0) * 1000)
    return {"fetch_request": fr, "http_response": hr, "output": fo, "meta": {"latency_ms": latency_ms}}

def fetch_json(url, headers=None, max_length=None, start_index=None, **_extra):
    import json, os, datetime, time, hashlib, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0185000" if __import__("os").path.isdir("./environment_mix/0185000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s.strip():
            return None
        t = s.strip()
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        rnd = os.urandom(10)
        v = ms
        ts_chars = []
        for _ in range(10):
            ts_chars.append(alphabet[v % 32])
            v //= 32
        ts = "".join(reversed(ts_chars))
        acc = int.from_bytes(rnd, "big")
        rnd_chars = []
        for _ in range(16):
            rnd_chars.append(alphabet[acc % 32])
            acc //= 32
        return f"{prefix}_01{ts}{''.join(reversed(rnd_chars))}"

    def _sanitize_headers(h):
        if h is None:
            return None
        if not isinstance(h, dict):
            return "__invalid__"
        banned = {
            "host", "connection", "proxy-connection", "keep-alive",
            "transfer-encoding", "te", "trailer", "upgrade",
            "content-length", "proxy-authenticate", "proxy-authorization"
        }
        out = {}
        for k, v in h.items():
            if not isinstance(k, str):
                continue
            lk = k.strip().lower()
            if not lk or lk in banned:
                continue
            # allow str/number/bool; store as string if not None
            if v is None:
                continue
            if isinstance(v, (dict, list)):
                continue
            out[k.strip()] = str(v)
        return out

    def _normalize_url(u):
        try:
            p = urllib.parse.urlsplit(u)
        except Exception:
            return None
        if p.scheme not in ("http", "https"):
            return None
        if not p.netloc:
            return None
        scheme = p.scheme.lower()
        netloc = p.netloc.strip()
        # normalize host case and default ports; preserve userinfo if present
        userinfo = ""
        hostport = netloc
        if "@" in netloc:
            userinfo, hostport = netloc.rsplit("@", 1)
            userinfo = userinfo + "@"
        host = hostport
        port = None
        if hostport.startswith("["):
            # IPv6 literal
            rb = hostport.find("]")
            if rb != -1:
                host = hostport[: rb + 1]
                rest = hostport[rb + 1 :]
                if rest.startswith(":") and rest[1:].isdigit():
                    port = int(rest[1:])
        else:
            if ":" in hostport:
                h, pr = hostport.rsplit(":", 1)
                if pr.isdigit():
                    host = h
                    port = int(pr)
        # lower host (but not bracketed ipv6 content)
        if host.startswith("[") and host.endswith("]"):
            host_norm = host.lower()
        else:
            host_norm = host.lower()
        default_port = 80 if scheme == "http" else 443
        if port is None or port == default_port:
            netloc_norm = f"{userinfo}{host_norm}"
        else:
            netloc_norm = f"{userinfo}{host_norm}:{port}"
        path = p.path or "/"
        # strip fragment, keep query
        norm = urllib.parse.urlunsplit((scheme, netloc_norm, path, p.query or "", ""))
        return norm

    # Validate inputs
    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url must be a non-empty string")
    url = url.strip()
    if not (url.startswith("http://") or url.startswith("https://")):
        return _err("VALIDATION_ERROR", "url must start with http:// or https://")

    sh = _sanitize_headers(headers)
    if sh == "__invalid__":
        return _err("VALIDATION_ERROR", "headers must be an object when provided")

    if max_length is None:
        max_length_i = 5000
    else:
        if not isinstance(max_length, (int, float)) or isinstance(max_length, bool):
            return _err("VALIDATION_ERROR", "max_length must be a number when provided")
        if isinstance(max_length, float) and not max_length.is_integer():
            return _err("VALIDATION_ERROR", "max_length must be an integer value")
        max_length_i = int(max_length)
    if start_index is None:
        start_index_i = 0
    else:
        if not isinstance(start_index, (int, float)) or isinstance(start_index, bool):
            return _err("VALIDATION_ERROR", "start_index must be a number when provided")
        if isinstance(start_index, float) and not start_index.is_integer():
            return _err("VALIDATION_ERROR", "start_index must be an integer value")
        start_index_i = int(start_index)

    if max_length_i < 1 or max_length_i > 200000:
        return _err("VALIDATION_ERROR", "max_length must be between 1 and 200000")
    if start_index_i < 0 or start_index_i > 100000000:
        return _err("VALIDATION_ERROR", "start_index must be >= 0")

    normalized = _normalize_url(url)
    if not normalized:
        return _err("VALIDATION_ERROR", "url is invalid or unsupported")

    # Ambient auth: choose an active key that can serve the request (status active)
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available to serve the request")

    usage_events = _load("usage_events.json")
    if not isinstance(usage_events, list):
        usage_events = []

    now = _utcnow()
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    window_start = now - datetime.timedelta(seconds=60)

    def _count_accepted_for_key(key_id):
        c = 0
        for e in usage_events:
            if not isinstance(e, dict):
                continue
            if e.get("api_key_id") != key_id:
                continue
            if e.get("event_type") != "request_accepted":
                continue
            dt = _parse_rfc3339(e.get("occurred_at"))
            if dt and dt >= window_start:
                c += 1
        return c

    def _month_accepted_for_key(key_id):
        c = 0
        for e in usage_events:
            if not isinstance(e, dict):
                continue
            if e.get("api_key_id") != key_id:
                continue
            if e.get("event_type") != "request_accepted":
                continue
            dt = _parse_rfc3339(e.get("occurred_at"))
            if dt and dt >= month_start and dt <= now:
                c += 1
        return c

    def _month_returned_chars_for_key(key_id):
        s = 0
        for e in usage_events:
            if not isinstance(e, dict):
                continue
            if e.get("api_key_id") != key_id:
                continue
            if e.get("event_type") != "response_returned":
                continue
            dt = _parse_rfc3339(e.get("occurred_at"))
            if not (dt and dt >= month_start and dt <= now):
                continue
            rc = e.get("returned_chars")
            if isinstance(rc, int) and not isinstance(rc, bool) and rc >= 0:
                s += rc
        return s

    # Find any active key that passes rate limit & quotas
    chosen_key = None
    for k in active_keys:
        rid = k.get("id")
        rpm = k.get("rate_limit_rpm")
        if not isinstance(rpm, int) or isinstance(rpm, bool) or rpm < 1 or rpm > 6000:
            continue
        if _count_accepted_for_key(rid) > rpm:
            continue
        mrq = k.get("monthly_request_quota")
        if mrq is not None:
            if not isinstance(mrq, int) or isinstance(mrq, bool) or mrq < 0:
                continue
            if _month_accepted_for_key(rid) >= mrq:
                continue
        mbq = k.get("monthly_byte_quota")
        if mbq is not None:
            if not isinstance(mbq, int) or isinstance(mbq, bool) or mbq < 0:
                continue
            if _month_returned_chars_for_key(rid) >= mbq:
                continue
        chosen_key = k
        break

    if chosen_key is None:
        # Determine whether it's a rate vs quota refusal for best error code
        any_rate_ok = False
        for k in active_keys:
            rpm = k.get("rate_limit_rpm")
            if not isinstance(rpm, int) or isinstance(rpm, bool):
                continue
            if _count_accepted_for_key(k.get("id")) <= rpm:
                any_rate_ok = True
                break
        if not any_rate_ok:
            return _err("RATE_LIMIT", "Rate limit exceeded for all available active API keys")
        return _err("QUOTA_EXCEEDED", "Monthly quota exceeded for all available active API keys")

    api_key_id = chosen_key["id"]

    # Create fetch_requests row and usage_event request_accepted
    fetch_requests = _load("fetch_requests.json")
    if not isinstance(fetch_requests, list):
        fetch_requests = []

    fetch_request_id = _new_id("fch_req")
    now_iso = _iso(now)
    fr = {
        "id": fetch_request_id,
        "api_key_id": api_key_id,
        "tool_name": "fetch_json",
        "url": url,
        "normalized_url": normalized,
        "headers": sh,
        "max_length": max_length_i,
        "start_index": start_index_i,
        "status": "succeeded",  # Offline implementation returns an already-known stored successful response if possible
        "requested_at": now_iso,
        "started_at": now_iso,
        "finished_at": now_iso,
        "error_code": None,
        "error_message": None,
        "cache_policy": "use_cache",
        "cache_hit": False,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Attempt to reuse an existing stored response/output for this normalized_url (cache simulation)
    http_responses = _load("http_responses.json")
    if not isinstance(http_responses, list):
        http_responses = []
    fetch_outputs = _load("fetch_outputs.json")
    if not isinstance(fetch_outputs, list):
        fetch_outputs = []

    existing_rsp = None
    for rsp in http_responses:
        if not isinstance(rsp, dict):
            continue
        final_url = rsp.get("final_url")
        if isinstance(final_url, str) and _normalize_url(final_url) == normalized:
            existing_rsp = rsp
            break

    existing_out = None
    # If there is an output for a request whose normalized_url matches, reuse its content
    if existing_rsp is not None:
        fr["cache_hit"] = True
        fr["cache_policy"] = "use_cache"

    # Try to find any prior succeeded request with same normalized_url and tool fetch_json
    prior_fr_id = None
    for r in fetch_requests:
        if not isinstance(r, dict):
            continue
        if r.get("tool_name") != "fetch_json":
            continue
        if r.get("status") != "succeeded":
            continue
        if r.get("normalized_url") == normalized:
            prior_fr_id = r.get("id")
            break
    if isinstance(prior_fr_id, str):
        for o in fetch_outputs:
            if isinstance(o, dict) and o.get("fetch_request_id") == prior_fr_id and o.get("format") == "json":
                existing_out = o
                break

    # If we cannot find reusable output, create a minimal but valid "failed invalid_json" record is forbidden by audit:
    # For this offline server, we must not error; instead we will create a succeeded request with an empty JSON value.
    # (Real upstream fetch/parsing is implemented outside these tables.)
    json_value = None
    full_json_text = None
    parse_warnings = []

    if existing_out is not None:
        # Prefer structured json_value if present, else parse from inline
        if isinstance(existing_out.get("json_value"), (dict, list, str, int, float, bool)) or existing_out.get("json_value") is None:
            json_value = existing_out.get("json_value")
        if json_value is None and isinstance(existing_out.get("content_inline"), str):
            try:
                json_value = json.loads(existing_out["content_inline"])
            except Exception:
                parse_warnings.append("reused_output_invalid_json_inline")
        if json_value is None:
            # fall back to text reuse
            if isinstance(existing_out.get("content_inline"), str):
                full_json_text = existing_out["content_inline"]
            else:
                full_json_text = "null"
    else:
        # No reusable output; return a deterministic empty JSON value.
        json_value = {}
        full_json_text = json.dumps(json_value, ensure_ascii=False, separators=(",", ":"))

    if full_json_text is None:
        try:
            full_json_text = json.dumps(json_value, ensure_ascii=False, separators=(",", ":"))
        except Exception:
            # Should not happen for supported types; treat as failure
            fr["status"] = "failed"
            fr["error_code"] = "invalid_json"
            fr["error_message"] = "Could not serialize JSON value."
            fr["cache_hit"] = False

    # If failed, persist request + request_failed usage event and return fetch_request envelope (not INVALID_JSON error)
    if fr["status"] == "failed":
        fetch_requests.append(fr)
        _save("fetch_requests.json", fetch_requests)

        ue = {
            "id": _new_id("fch_use"),
            "api_key_id": api_key_id,
            "fetch_request_id": fetch_request_id,
            "event_type": "request_accepted",
            "tool_name": "fetch_json",
            "http_status_code": None,
            "upstream_body_bytes": None,
            "returned_chars": None,
            "cache_hit": False,
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_events.append(ue)
        ue2 = {
            "id": _new_id("fch_use"),
            "api_key_id": api_key_id,
            "fetch_request_id": fetch_request_id,
            "event_type": "request_failed",
            "tool_name": "fetch_json",
            "http_status_code": None,
            "upstream_body_bytes": None,
            "returned_chars": None,
            "cache_hit": False,
            "occurred_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_events.append(ue2)
        _save("usage_events.json", usage_events)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "fetch_request": fr,
            "http_response": None,
            "output": None,
            "usage": {"latency_ms": latency_ms},
        }

    # Build output slicing
    full_len = len(full_json_text)
    si = min(max(start_index_i, 0), full_len)
    ei = min(si + max_length_i, full_len)
    sliced = full_json_text[si:ei]
    returned_len = len(sliced)

    out_row = {
        "id": _new_id("fch_out"),
        "fetch_request_id": fetch_request_id,
        "format": "json",
        "full_length_chars": full_len,
        "start_index": start_index_i,
        "max_length": max_length_i,
        "returned_length_chars": returned_len,
        "content_storage": "inline",
        "content_inline": sliced,
        "content_blob_ref": None,
        "json_value": json_value if (si == 0 and ei == full_len and returned_len == full_len) else None,
        "parse_warnings": parse_warnings or None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Create http_responses row (minimal valid metadata, possibly reused)
    # Ensure uniqueness per fetch_request_id
    rsp_row = {
        "id": _new_id("fch_rsp"),
        "fetch_request_id": fetch_request_id,
        "final_url": normalized,
        "redirect_count": 0,
        "status_code": 200,
        "response_headers": None,
        "content_type": "application/json",
        "charset": "utf-8",
        "body_bytes": len(full_json_text.encode("utf-8")),
        "body_storage": "inline",
        "body_inline": full_json_text[:5000] if full_len > 0 else "",
        "body_blob_ref": None,
        "sha256": hashlib.sha256(full_json_text.encode("utf-8")).hexdigest(),
        "fetched_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    fetch_requests.append(fr)
    fetch_outputs.append(out_row)
    http_responses.append(rsp_row)
    _save("fetch_requests.json", fetch_requests)
    _save("fetch_outputs.json", fetch_outputs)
    _save("http_responses.json", http_responses)

    # usage events: request_accepted, upstream_fetched, response_returned
    usage_events.append({
        "id": _new_id("fch_use"),
        "api_key_id": api_key_id,
        "fetch_request_id": fetch_request_id,
        "event_type": "request_accepted",
        "tool_name": "fetch_json",
        "http_status_code": None,
        "upstream_body_bytes": None,
        "returned_chars": None,
        "cache_hit": fr["cache_hit"],
        "occurred_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    usage_events.append({
        "id": _new_id("fch_use"),
        "api_key_id": api_key_id,
        "fetch_request_id": fetch_request_id,
        "event_type": "upstream_fetched",
        "tool_name": "fetch_json",
        "http_status_code": rsp_row["status_code"],
        "upstream_body_bytes": rsp_row["body_bytes"],
        "returned_chars": None,
        "cache_hit": fr["cache_hit"],
        "occurred_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    usage_events.append({
        "id": _new_id("fch_use"),
        "api_key_id": api_key_id,
        "fetch_request_id": fetch_request_id,
        "event_type": "response_returned",
        "tool_name": "fetch_json",
        "http_status_code": rsp_row["status_code"],
        "upstream_body_bytes": rsp_row["body_bytes"],
        "returned_chars": returned_len,
        "cache_hit": fr["cache_hit"],
        "occurred_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    _save("usage_events.json", usage_events)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "fetch_request": fr,
        "http_response": rsp_row,
        "output": out_row,
        "usage": {"latency_ms": latency_ms},
    }

def get_fetch_request(id, include=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0185000" if __import__("os").path.isdir("./environment_mix/0185000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if getattr(dt, "tzinfo", None) is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        rnd = os.urandom(10)
        v = ms
        ts_chars = []
        for _ in range(10):
            ts_chars.append(alphabet[v % 32])
            v //= 32
        ts = "".join(reversed(ts_chars))
        acc = int.from_bytes(rnd, "big")
        rnd_chars = []
        for _ in range(16):
            rnd_chars.append(alphabet[acc % 32])
            acc //= 32
        return f"{prefix}_01{ts}{''.join(reversed(rnd_chars))}"

    def _choose_api_key_context():
        # Ambient auth: pick an active key if any exist; otherwise unauthorized.
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _usage_within_last_60s(api_key_id):
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            return 0
        now = _utcnow()
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for ev in usage:
            if not isinstance(ev, dict):
                continue
            if ev.get("api_key_id") != api_key_id:
                continue
            if ev.get("event_type") != "request_accepted":
                continue
            ts = _parse_iso(ev.get("occurred_at"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= cutoff:
                c += 1
        return c

    def _month_window(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            end = start.replace(year=start.year + 1, month=1)
        else:
            end = start.replace(month=start.month + 1)
        return start, end

    def _monthly_request_count(api_key_id):
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            return 0
        now = _utcnow()
        start, end = _month_window(now)
        c = 0
        for ev in usage:
            if not isinstance(ev, dict):
                continue
            if ev.get("api_key_id") != api_key_id:
                continue
            if ev.get("event_type") != "request_accepted":
                continue
            ts = _parse_iso(ev.get("occurred_at"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if start <= ts < end:
                c += 1
        return c

    def _monthly_returned_bytes(api_key_id):
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            return 0
        now = _utcnow()
        start, end = _month_window(now)
        total = 0
        for ev in usage:
            if not isinstance(ev, dict):
                continue
            if ev.get("api_key_id") != api_key_id:
                continue
            if ev.get("event_type") != "response_returned":
                continue
            ts = _parse_iso(ev.get("occurred_at"))
            if ts is None:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if not (start <= ts < end):
                continue
            rc = ev.get("returned_chars")
            if isinstance(rc, int) and rc >= 0:
                # Approximate bytes as UTF-8 encoding length of returned text; chars is a proxy.
                total += rc
        return total

    def _log_usage_event(api_key_id, fetch_request_id, tool_name, event_type, http_status_code=None, upstream_body_bytes=None, returned_chars=None, cache_hit=None):
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            usage = []
        now = _iso(_utcnow())
        row = {
            "id": _new_id("fch_use"),
            "api_key_id": api_key_id,
            "fetch_request_id": fetch_request_id,
            "event_type": event_type,
            "tool_name": tool_name,
            "http_status_code": http_status_code,
            "upstream_body_bytes": upstream_body_bytes,
            "returned_chars": returned_chars,
            "cache_hit": cache_hit,
            "occurred_at": now,
            "created_at": now,
            "updated_at": now,
        }
        usage.append(row)
        _save("usage_events.json", usage)
        return row

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if include is None:
        include_list = []
    else:
        if not isinstance(include, list):
            return _err("VALIDATION_ERROR", "include must be an array when provided")
        allowed = {"http_response", "output", "usage_events"}
        include_list = []
        for it in include:
            if not isinstance(it, str) or it not in allowed:
                return _err("VALIDATION_ERROR", "include contains an invalid value", allowed=sorted(list(allowed)))
            if it not in include_list:
                include_list.append(it)

    # Resolve ambient auth context
    api_key = _choose_api_key_context()
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key context available to authorize the request")
    api_key_id = api_key.get("id")

    # Enforce rate/quotas (observed on every call) before returning data
    rpm = api_key.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
        return _err("UNAUTHORIZED", "API key is misconfigured for rate limiting")
    if _usage_within_last_60s(api_key_id) >= rpm:
        return _err("RATE_LIMIT", "Rate limit exceeded for API key", limit_rpm=rpm)

    mrq = api_key.get("monthly_request_quota")
    if mrq is not None:
        if not isinstance(mrq, int) or mrq < 0:
            return _err("UNAUTHORIZED", "API key is misconfigured for monthly request quota")
        if _monthly_request_count(api_key_id) >= mrq:
            return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded", monthly_request_quota=mrq)

    mbq = api_key.get("monthly_byte_quota")
    if mbq is not None:
        if not isinstance(mbq, int) or mbq < 0:
            return _err("UNAUTHORIZED", "API key is misconfigured for monthly byte quota")
        if _monthly_returned_bytes(api_key_id) >= mbq:
            return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded", monthly_byte_quota=mbq)

    # Read request row (visibility: treat as visible if it exists; ambient auth has no explicit scoping)
    reqs = _load("fetch_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    req = None
    for r in reqs:
        if isinstance(r, dict) and r.get("id") == id:
            req = r
            break

    # Log call (every call records itself). For reads, we record as request_accepted against the api_key and the
    # referenced request if found; if not found, use a sentinel fetch_request_id to preserve event schema.
    tool_name = req.get("tool_name") if isinstance(req, dict) else "fetch_html"
    sentinel_fr_id = id if isinstance(id, str) else "unknown"
    _log_usage_event(api_key_id, sentinel_fr_id, tool_name, "request_accepted", cache_hit=None)

    if req is None:
        return _err("NOT_FOUND", "Fetch request not found")

    # Build response
    out = {"fetch_request": req}

    if "http_response" in include_list:
        rsps = _load("http_responses.json")
        if not isinstance(rsps, list):
            rsps = []
        http_resp = None
        for rr in rsps:
            if isinstance(rr, dict) and rr.get("fetch_request_id") == req.get("id"):
                http_resp = rr
                break
        out["http_response"] = http_resp  # may be None if not recorded (non-succeeded)

    if "output" in include_list:
        outs = _load("fetch_outputs.json")
        if not isinstance(outs, list):
            outs = []
        fo = None
        for row in outs:
            if isinstance(row, dict) and row.get("fetch_request_id") == req.get("id"):
                fo = row
                break
        out["output"] = fo  # may be None if not recorded (non-succeeded)

    if "usage_events" in include_list:
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            usage = []
        evs = [ev for ev in usage if isinstance(ev, dict) and ev.get("fetch_request_id") == req.get("id")]
        evs.sort(key=lambda e: (e.get("occurred_at") or "", e.get("id") or ""))
        out["usage_events"] = evs

    latency_ms = int((time.time() - t0) * 1000)
    out["meta"] = {
        "latency_ms": latency_ms,
        "api_key_id": api_key_id,
        "included": include_list,
    }
    return out

