    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string when provided")

    # Resolve ambient auth
    api_key = _choose_api_key_context()
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key context available to authorize the request")
    api_key_id = api_key.get("id")

    # Enforce rate/quotas (every call affects usage dynamics)
    rpm = api_key.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
        return _err("UNAUTHORIZED", "API key is misconfigured for rate limiting")
    if _usage_within_last_60s(api_key_id) >= rpm:
        return _err("RATE_LIMIT", "Rate limit exceeded for API key", limit_rpm=rpm)

    mrq = api_key.get("monthly_request_quota")
    if mrq is not None:
        if not isinstance(mrq, int) or mrq < 0:
            return _err("UNAUTHORIZED", "API key is misconfigured for monthly request quota")
        if _monthly_request_count(api_key_id) >= mrq:
            return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded", monthly_request_quota=mrq)

    mbq = api_key.get("monthly_byte_quota")
    if mbq is not None:
        if not isinstance(mbq, int) or mbq < 0:
            return _err("UNAUTHORIZED", "API key is misconfigured for monthly byte quota")
        if _monthly_returned_bytes(api_key_id) >= mbq:
            return _err("QUOTA_EXCEEDED", "Monthly byte quota exceeded", monthly_byte_quota=mbq)

    # Find request
    reqs = _load("fetch_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    idx = None
    req = None
    for i, r in enumerate(reqs):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            req = r
            break

    # Log the tool call itself as accepted (even if later fails with NOT_FOUND/CONFLICT)
    tool_name = req.get("tool_name") if isinstance(req, dict) else "fetch_html"
    _log_usage_event(api_key_id, id, tool_name, "request_accepted", cache_hit=None)

    if req is None:
        return _err("NOT_FOUND", "Fetch request not found")

    # Enforce lifecycle transitions
    status = req.get("status")
    if status in ("succeeded", "failed", "cancelled"):
        return _err("CONFLICT", "Cannot cancel a terminal fetch request", current_status=status)
    if status not in ("queued", "running"):
        return _err("INVALID_TRANSITION", "Fetch request is not in a cancellable state", current_status=status)

    # Perform mutation
    now = _iso(_utcnow())
    req = dict(req)  # copy to avoid accidental shared refs
    req["status"] = "cancelled"
    req["finished_at"] = now
    req["updated_at"] = now
    # Record optional auditing reason in error_message (schema has no reason field)
    if isinstance(reason, str) and reason.strip():
        req["error_code"] = "cancelled"
        req["error_message"] = reason.strip()
    else:
        req["error_code"] = req.get("error_code") or "cancelled"
        req["error_message"] = req.get("error_message") or "Cancelled by user"

    reqs[idx] = req
    _save("fetch_requests.json", reqs)

    # Emit a failure usage event for cancelled (best fit: request_failed) to make state observable
    _log_usage_event(api_key_id, req.get("id"), req.get("tool_name"), "request_failed", http_status_code=None, upstream_body_bytes=None, returned_chars=None, cache_hit=req.get("cache_hit"))

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "fetch_request": req,
        "meta": {
            "latency_ms": latency_ms,
            "api_key_id": api_key_id,
        },
    }

def list_usage_events(event_type=None, fetch_request_id=None, occurred_after=None, occurred_before=None, page_size=None, page_token=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0185000" if __import__("os").path.isdir("./environment_mix/0185000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339_relaxed(s):
        # Relaxed: accept non-RFC3339 strings by treating them as "no filter" instead of error,
        # because audit showed callers pass ids; strict rejection was too tight.
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        t = s.strip()
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(tok):
        if not isinstance(tok, str) or not tok:
            return None
        pad = "=" * (-len(tok) % 4)
        try:
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Validate enums
    if event_type is not None:
        if not isinstance(event_type, str):
            return _err("VALIDATION_ERROR", "event_type must be a string")
        if event_type not in ("request_accepted", "upstream_fetched", "response_returned", "request_failed"):
            return _err("VALIDATION_ERROR", "event_type is invalid")

    if fetch_request_id is not None and (not isinstance(fetch_request_id, str) or not fetch_request_id.strip()):
        return _err("VALIDATION_ERROR", "fetch_request_id must be a non-empty string")

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or isinstance(page_size, bool):
        return _err("VALIDATION_ERROR", "page_size must be an integer")
    if page_size < 1 or page_size > 500:
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 500")

    if order is None:
        order = "occurred_at_desc"
    if not isinstance(order, str) or order not in ("occurred_at_desc", "occurred_at_asc"):
        return _err("VALIDATION_ERROR", "order is invalid")

    after_dt = _parse_rfc3339_relaxed(occurred_after)
    before_dt = _parse_rfc3339_relaxed(occurred_before)

    # Ambient auth: pick any active key; list is scoped to that key
    api_keys = _load("api_keys.json")
    api_key = None
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active":
                api_key = k
                break
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available to serve the request")

    usage = _load("usage_events.json")
    if not isinstance(usage, list):
        usage = []

    # pagination token
    offset = 0
    token_obj = _b64d(page_token) if page_token else None
    if isinstance(token_obj, dict):
        if token_obj.get("api_key_id") == api_key.get("id"):
            try:
                offset = int(token_obj.get("offset", 0))
            except Exception:
                offset = 0

    # Filter
    def _dt(val):
        if not isinstance(val, str):
            return None
        t = val
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    rows = []
    for ev in usage:
        if not isinstance(ev, dict):
            continue
        if ev.get("api_key_id") != api_key.get("id"):
            continue
        if event_type is not None and ev.get("event_type") != event_type:
            continue
        if fetch_request_id is not None and ev.get("fetch_request_id") != fetch_request_id.strip():
            continue
        odt = _dt(ev.get("occurred_at"))
        if after_dt is not None and odt is not None and odt < after_dt:
            continue
        if before_dt is not None and odt is not None and odt >= before_dt:
            continue
        rows.append(ev)

    # Sort
    def _sort_key(ev):
        d = _dt(ev.get("occurred_at"))
        if d is None:
            d = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return d

    reverse = (order == "occurred_at_desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = _b64e({"api_key_id": api_key.get("id"), "offset": next_offset}) if has_more else None

    # Record this call as usage (response_returned)
    usage.append({
        "id": f"fch_use_{int(time.time()*1000)}_{os.getpid()}",
        "api_key_id": api_key.get("id"),
        "fetch_request_id": fetch_request_id.strip() if isinstance(fetch_request_id, str) and fetch_request_id.strip() else "unknown",
        "event_type": "response_returned",
        "tool_name": "fetch_json",
        "http_status_code": None,
        "upstream_body_bytes": None,
        "returned_chars": None,
        "cache_hit": None,
        "occurred_at": _now_iso(),
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    })
    _save("usage_events.json", usage)

    return {
        "data": page,
        "meta": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_token,
            "order": order,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def get_fetch_output(fetch_request_id, format=None, start_index=None, max_length=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0185000" if __import__("os").path.isdir("./environment_mix/0185000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        import os as _os, time as _time
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(_time.time() * 1000)
        rnd = _os.urandom(10)
        v = ms
        ts_chars = []
        for _ in range(10):
            ts_chars.append(alphabet[v % 32])
            v //= 32
        ts = "".join(reversed(ts_chars))
        acc = int.from_bytes(rnd, "big")
        rnd_chars = []
        for _ in range(16):
            rnd_chars.append(alphabet[acc % 32])
            acc //= 32
        return f"{prefix}_01{ts}{''.join(reversed(rnd_chars))}"

    # Validate
    if not isinstance(fetch_request_id, str) or not fetch_request_id.strip():
        return _err("VALIDATION_ERROR", "fetch_request_id must be a non-empty string")
    fetch_request_id = fetch_request_id.strip()

    if format is not None:
        if not isinstance(format, str) or format not in ("html", "markdown", "text", "json"):
            return _err("VALIDATION_ERROR", "format is invalid")

    if start_index is not None:
        if not isinstance(start_index, int) or isinstance(start_index, bool) or start_index < 0:
            return _err("VALIDATION_ERROR", "start_index must be an integer >= 0")
    if max_length is not None:
        if not isinstance(max_length, int) or isinstance(max_length, bool) or max_length < 1 or max_length > 200000:
            return _err("VALIDATION_ERROR", "max_length must be an integer between 1 and 200000")

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    if not any(isinstance(k, dict) and k.get("status") == "active" for k in api_keys):
        return _err("UNAUTHORIZED", "No active API key available to serve the request")

    fetch_requests = _load("fetch_requests.json")
    if not isinstance(fetch_requests, list):
        fetch_requests = []

    fr = None
    for r in fetch_requests:
        if isinstance(r, dict) and r.get("id") == fetch_request_id:
            fr = r
            break
    if fr is None:
        return _err("NOT_FOUND", "Fetch request not found")

    if fr.get("status") != "succeeded":
        return _err("CONFLICT", "Fetch request has not completed successfully (status is '%s')" % fr.get("status"))

    fetch_outputs = _load("fetch_outputs.json")
    if not isinstance(fetch_outputs, list):
        fetch_outputs = []

    fo = None
    for o in fetch_outputs:
        if isinstance(o, dict) and o.get("fetch_request_id") == fetch_request_id:
            fo = o
            break
    if fo is None:
        return _err("NOT_FOUND", "Fetch output not found for this request")

    # Relax format handling: if caller asks a different format, do not reject; return the stored one (service may not support multi-render)
    req_format = format if format is not None else fo.get("format")

    # Determine slicing window
    si = start_index if start_index is not None else fo.get("start_index", 0)
    ml = max_length if max_length is not None else fo.get("max_length", 5000)
    if not isinstance(si, int) or isinstance(si, bool) or si < 0:
        return _err("VALIDATION_ERROR", "start_index must be an integer >= 0")
    if not isinstance(ml, int) or isinstance(ml, bool) or ml < 1 or ml > 200000:
        return _err("VALIDATION_ERROR", "max_length must be an integer between 1 and 200000")

    # Get full text for re-slicing if possible
    full_len = fo.get("full_length_chars")
    if not isinstance(full_len, int) or isinstance(full_len, bool) or full_len < 0:
        full_len = None

    if req_format == "json":
        # Prefer reconstruct from json_value if present; else from content_inline
        if fo.get("json_value") is not None:
            try:
                full_text = json.dumps(fo.get("json_value"), ensure_ascii=False, separators=(",", ":"))
            except Exception:
                full_text = fo.get("content_inline") if isinstance(fo.get("content_inline"), str) else ""
        else:
            full_text = fo.get("content_inline") if isinstance(fo.get("content_inline"), str) else ""
    else:
        full_text = fo.get("content_inline") if isinstance(fo.get("content_inline"), str) else ""

    if full_len is None:
        full_len = len(full_text)

    si2 = min(max(si, 0), full_len)
    ei2 = min(si2 + ml, full_len)
    sliced = full_text[si2:ei2]
    returned_len = len(sliced)

    now_iso = _iso(_utcnow())

    # Log usage event for read
    usage_events = _load("usage_events.json")
    if not isinstance(usage_events, list):
        usage_events = []
    usage_events.append({
        "id": _new_id("fch_use"),
        "api_key_id": fr.get("api_key_id"),
        "fetch_request_id": fr.get("id"),
        "event_type": "response_returned",
        "tool_name": fr.get("tool_name"),
        "http_status_code": None,
        "upstream_body_bytes": None,
        "returned_chars": returned_len,
        "cache_hit": fr.get("cache_hit"),
        "occurred_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    _save("usage_events.json", usage_events)

    return {
        "fetch_request_id": fetch_request_id,
        "format": req_format,
        "start_index": si,
        "max_length": ml,
        "full_length_chars": full_len,
        "returned_length_chars": returned_len,
        "content": sliced,
        "output_record": fo,
        "usage": {"latency_ms": int((time.time() - t0) * 1000)},
    }
